SourceCode.Declaration:
/// <summary>
/// extension of form PurchTable
/// </summary>
[ExtensionOf(formStr(PurchTable))]
final class AVAPurchTableFrm_Extension
{
}

Method.Source:
/// <summary>
/// AVA <c>avaGetDiffCategoryOrders</c>
/// </summary>
/// <param name = "_avaPurchTable_fds">FormDataSource</param>
/// <returns>str</returns>
public str avaGetDiffCategoryOrders(FormDataSource _avaPurchTable_fds)
{
    str avaPurchOrders;
    PurchTable avaPurchTableLoc;

    avaPurchTableLoc = _avaPurchTable_fds.getFirst(true);
    if(!avaPurchTableLoc)
    {
        avaPurchTableLoc = _avaPurchTable_fds.cursor();
    }

    while(avaPurchTableLoc.RecId)
    {
        if(this.avaCheckLineDiffCategory(avaPurchTableLoc))
        {
            if(avaPurchOrders != '')
            {
                avaPurchOrders += ', ';
            }

            avaPurchOrders += avaPurchTableLoc.PurchId;
        }

        avaPurchTableLoc = _avaPurchTable_fds.getNext();
    }

    return avaPurchOrders;
}

/// <summary>
/// AVA <c>avaConfirmPurchTablesDialog</c>
/// </summary>
/// <param name = "_avaPurchOrders">str</param>
/// <returns>DialogButton</returns>
public DialogButton avaConfirmPurchTablesDialog(str _avaPurchOrders)
{
    str strMessage = strFmt(SysLabel::labelId2String2("@NDX:NDAConfirmPurchTableDialog"), _avaPurchOrders);
    return Box::yesNo(strMessage,DialogButton::No);
}

/// <summary>
/// AVA <c>avaCheckLineDiffCategory</c>
/// </summary>
/// <param name = "_purchTable">PurchTable</param>
/// <returns>boolean</returns>
public boolean avaCheckLineDiffCategory(PurchTable _purchTable)
{
    PurchCategory purchCategoryLoc;
    PurchLine avaPurchLineLoc;

    select firstonly ProcurementCategory from avaPurchLineLoc
        order by avaPurchLineLoc.LineNumber asc
        where avaPurchLineLoc.PurchId == _purchTable.PurchId;

    purchCategoryLoc = avaPurchLineLoc.ProcurementCategory;

    select firstonly avaPurchLineLoc
        where avaPurchLineLoc.PurchId == _purchTable.PurchId
        && avaPurchLineLoc.ProcurementCategory != purchCategoryLoc;

    return avaPurchLineLoc.RecId;
}
